import{_ as t,o as e,c as i,a2 as s}from"./chunks/framework.Bqa2y7hU.js";const k=JSON.parse('{"title":"QQ 官方：WebSocket 网关","description":"用 WebSocket 网关方式接入 QQ 官方开放平台机器人，不需要公网域名。","frontmatter":{"title":"QQ 官方：WebSocket 网关","description":"用 WebSocket 网关方式接入 QQ 官方开放平台机器人，不需要公网域名。"},"headers":[],"relativePath":"platforms/qq-official.md","filePath":"platforms/qq-official.md","lastUpdated":1789447036000}'),l={name:"platforms/qq-official.md"};function o(r,a,d,n,h,c){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="qq-官方-websocket-网关-🔗" tabindex="-1">QQ 官方：WebSocket 网关 🔗 <a class="header-anchor" href="#qq-官方-websocket-网关-🔗" aria-label="Permalink to &quot;QQ 官方：WebSocket 网关 🔗&quot;">​</a></h1><p>这是接入 QQ 官方机器人<strong>推荐的方式</strong>：框架主动去连 QQ 开放平台的网关，你不需要准备公网域名，也不需要配任何回调地址。适合绝大多数部署在普通云主机上的情况。</p><p>读完这页你能做到：在 QQ 开放平台拿到凭据，在控制台把机器人创建出来，并确认它显示为在线。</p><h2 id="_1-在-qq-开放平台创建机器人" tabindex="-1">1. 在 QQ 开放平台创建机器人 <a class="header-anchor" href="#_1-在-qq-开放平台创建机器人" aria-label="Permalink to &quot;1. 在 QQ 开放平台创建机器人&quot;">​</a></h2><p>先到 QQ 开放平台完成机器人应用的创建，这一步在平台侧做，不在本框架里。创建完成后你需要从平台上取两样东西：</p><table tabindex="0"><thead><tr><th>需要的东西</th><th>说明</th></tr></thead><tbody><tr><td><code>AppID</code></td><td>机器人应用的唯一标识</td></tr><tr><td><code>AppSecret</code></td><td>机器人应用的密钥，填进控制台后请妥善保管</td></tr></tbody></table><p>同时建议在平台上把机器人需要的权限先配好（不同机器人能开的权限不一样，以平台页面上的可选项为准）。</p><div class="warning custom-block"><p class="custom-block-title">前置条件不满足会连不上</p><p>机器人必须先在 QQ 开放平台配置完成，并且<strong>已经被拉进目标群</strong>，否则框架即使连上了网关，也收不到任何群消息。</p></div><h2 id="_2-在控制台添加机器人" tabindex="-1">2. 在控制台添加机器人 <a class="header-anchor" href="#_2-在控制台添加机器人" aria-label="Permalink to &quot;2. 在控制台添加机器人&quot;">​</a></h2><p>登录控制台，进入「我的机器人」，点「添加机器人」。</p><ul><li>第一步：平台选 <code>qq_official</code>（QQ 官方）</li><li>第二步：填下面这些字段</li></ul><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>名称</td><td>给机器人起个名字，只用于你在控制台里区分它，随意填</td></tr><tr><td><code>AppID</code></td><td>第 1 步从 QQ 开放平台拿到的值</td></tr><tr><td><code>AppSecret</code></td><td>第 1 步从 QQ 开放平台拿到的值</td></tr><tr><td>环境</td><td>填 <code>production</code>（正式）或 <code>sandbox</code>（沙箱），要和平台上机器人所处的环境一致</td></tr></tbody></table><p>填完提交即可，机器人<strong>创建后立即上线，不需要重启服务</strong>。</p><h2 id="_3-连接方式选-websocket-网关" tabindex="-1">3. 连接方式选 WebSocket 网关 <a class="header-anchor" href="#_3-连接方式选-websocket-网关" aria-label="Permalink to &quot;3. 连接方式选 WebSocket 网关&quot;">​</a></h2><p>在向导的连接方式一步选「WebSocket 网关」。</p><p>选它的好处是：</p><ul><li>不需要填回调地址，框架会主动连上平台</li><li>不需要公网域名，服务器在内网也能跑</li><li>防火墙只需要放行出站，不用对外开放入口</li></ul><p>如果你确实需要平台主动回调你（例如有固定公网域名并且希望走回调），改看 <a href="/RuaBot.Doc/platforms/qq-official-webhook">QQ 官方：Webhook 回调</a>。</p><h2 id="_4-确认在线" tabindex="-1">4. 确认在线 <a class="header-anchor" href="#_4-确认在线" aria-label="Permalink to &quot;4. 确认在线&quot;">​</a></h2><p>创建完成后进入机器人详情页，看「设置」Tab：</p><ul><li>适配器应显示为 <code>qq_official</code></li><li>连接方式应显示为 WebSocket 网关</li><li>状态应显示为在线</li></ul><p>再切到「日志」Tab，正常情况下能看到连接建立的相关输出。如果状态一直不在线，按下一节的清单逐条排查。</p><details class="details custom-block"><summary>截图占位</summary><p>截机器人详情页「设置」Tab，重点露出适配器、连接方式、状态三行以及下方的支持能力列表。</p></details><h2 id="_5-让机器人收到群里的消息" tabindex="-1">5. 让机器人收到群里的消息 <a class="header-anchor" href="#_5-让机器人收到群里的消息" aria-label="Permalink to &quot;5. 让机器人收到群里的消息&quot;">​</a></h2><p>机器人进了群不等于能收到全部消息。QQ 官方默认只在消息 <strong>@ 到机器人</strong>时分发给它。</p><p>要让机器人收到群内全量消息，需要在 QQ 开放平台为机器人取得「群全量消息」授权。这一步在平台侧完成，通常需要走申请流程。</p><div class="tip custom-block"><p class="custom-block-title">用「全量申请」插件生成授权深链</p><p>控制台的插件市场里有名为<strong>全量申请</strong>的插件，它能生成授权用的深链，省去你在平台页面里找入口的麻烦。装上并打开它的插件面板即可使用，安装方式见 <a href="/RuaBot.Doc/console/plugins">插件市场与安装</a>。</p></div><h2 id="_6-连不上怎么查" tabindex="-1">6. 连不上怎么查 <a class="header-anchor" href="#_6-连不上怎么查" aria-label="Permalink to &quot;6. 连不上怎么查&quot;">​</a></h2><p>按「症状 / 原因 / 处理方式」逐条对照。</p><h3 id="症状-状态一直是离线-日志里反复出现连接失败" tabindex="-1">症状：状态一直是离线，日志里反复出现连接失败 <a class="header-anchor" href="#症状-状态一直是离线-日志里反复出现连接失败" aria-label="Permalink to &quot;症状：状态一直是离线，日志里反复出现连接失败&quot;">​</a></h3><ul><li><strong>原因</strong>：<code>AppID</code> / <code>AppSecret</code> 填错，或复制时带了首尾空格。</li><li><strong>处理方式</strong>：到机器人详情页「设置」Tab 重新核对凭据；如果拿不准，直接在 QQ 开放平台重新生成一次 <code>AppSecret</code> 再填。</li></ul><h3 id="症状-状态在线-但群里发消息机器人没反应" tabindex="-1">症状：状态在线，但群里发消息机器人没反应 <a class="header-anchor" href="#症状-状态在线-但群里发消息机器人没反应" aria-label="Permalink to &quot;症状：状态在线，但群里发消息机器人没反应&quot;">​</a></h3><ul><li><strong>原因</strong>：机器人没被拉进群，或者消息没有 @ 到机器人，而「群全量消息」授权又没拿到。</li><li><strong>处理方式</strong>：先把机器人拉进群，在群里 @ 它试一次；如果 @ 有反应、不 @ 没反应，说明缺的是全量消息授权，用「全量申请」插件走一遍授权。</li></ul><h3 id="症状-使用了沙箱环境-但只有部分人能用" tabindex="-1">症状：使用了沙箱环境，但只有部分人能用 <a class="header-anchor" href="#症状-使用了沙箱环境-但只有部分人能用" aria-label="Permalink to &quot;症状：使用了沙箱环境，但只有部分人能用&quot;">​</a></h3><ul><li><strong>原因</strong>：环境和平台上机器人所处的环境对不上。</li><li><strong>处理方式</strong>：确认控制台里「环境」字段填的是 <code>production</code> 还是 <code>sandbox</code>，与 QQ 开放平台上一致即可。</li></ul><h3 id="症状-添加机器人时被拒绝-提示和额度有关" tabindex="-1">症状：添加机器人时被拒绝，提示和额度有关 <a class="header-anchor" href="#症状-添加机器人时被拒绝-提示和额度有关" aria-label="Permalink to &quot;症状：添加机器人时被拒绝，提示和额度有关&quot;">​</a></h3><ul><li><strong>原因</strong>：机器人数已经用满套餐额度。</li><li><strong>处理方式</strong>：删掉不用的机器人，或升级套餐，见 <a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a>。</li></ul><h3 id="需要抓日志时" tabindex="-1">需要抓日志时 <a class="header-anchor" href="#需要抓日志时" aria-label="Permalink to &quot;需要抓日志时&quot;">​</a></h3><p>日志在机器人详情页的「日志」Tab 里能直接看，不用登服务器。如果确实要在服务器上看：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux：跟踪服务日志（具体路径以你的部署方式为准）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xiaoyi-qq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows：在 PowerShell 中查看服务状态</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Service</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Where-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$_</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.Name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*xiaoyi*&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/platforms/qq-official-webhook">QQ 官方：Webhook 回调</a></li><li><a href="/RuaBot.Doc/platforms/callback">回调地址与公网域名</a></li><li><a href="/RuaBot.Doc/console/bots">我的机器人</a></li></ul>`,43)])])}const b=t(l,[["render",o]]);export{k as __pageData,b as default};
